sys_variable_value.value:
(function() {
    var publisher = new x_1295779_conflu_0.ConfluencePublisher();

    try {
        // adf_content is already a JSON string — pass directly to API methods
        var adfBody = adf_content;

        // Get source record for logging and version message resolution
        var sourceGr = new GlideRecord(source_table);
        if (!sourceGr.get(source_record_id)) {
            status = 'error';
            error_message = 'Source record not found: ' + source_table + '/' + source_record_id;
            page_id = '';
            page_url = '';
            version = '';
            return;
        }

        var response;
        var httpStatus;
        var responseBody;

        if (operation === 'create') {
            response = publisher._createPage(cloud_id, space_id, page_title, adfBody, parent_page_id);
            httpStatus = response.statusCode;
            responseBody = response.body;

            if (httpStatus >= 200 && httpStatus < 300) {
                var respObj = JSON.parse(responseBody);
                page_id = respObj.id || '';
                page_url = (respObj._links && respObj._links.base) ? respObj._links.base + respObj._links.webui : '';
                version = (respObj.version && respObj.version.number) ? String(respObj.version.number) : '1';
                status = 'success';
                error_message = '';

                // Upsert page link for tracking
                publisher._upsertPageLink(source_table, source_record_id, page_id, publishing_definition, version);
                // Log success
                publisher._logPublishRun(publishing_definition, sourceGr, 'create', 'success', httpStatus, page_id, page_url, version, '');
            } else {
                var errMsg = '';
                try {
                    var errObj = JSON.parse(responseBody);
                    errMsg = errObj.message || errObj.title || responseBody;
                } catch (e) {
                    errMsg = responseBody;
                }
                status = 'error';
                error_message = errMsg;
                page_id = '';
                page_url = '';
                version = '';
                publisher._logPublishRun(publishing_definition, sourceGr, 'create', 'error', httpStatus, '', '', '', errMsg, JSON.stringify({ spaceId: space_id, title: page_title }));
            }

        } else if (operation === 'update') {
            var versionMsg = version_message || '';
            var versionNum = parseInt(current_version, 10) || 0;

            response = publisher._updatePage(cloud_id, existing_page_id, page_title, adfBody, versionNum, versionMsg, sourceGr);
            httpStatus = response.statusCode;
            responseBody = response.body;

            if (httpStatus >= 200 && httpStatus < 300) {
                var updObj = JSON.parse(responseBody);
                page_id = updObj.id || existing_page_id;
                page_url = (updObj._links && updObj._links.base) ? updObj._links.base + updObj._links.webui : '';
                version = (updObj.version && updObj.version.number) ? String(updObj.version.number) : String(versionNum + 1);
                status = 'success';
                error_message = '';

                // Upsert page link for tracking
                publisher._upsertPageLink(source_table, source_record_id, page_id, publishing_definition, version);
                // Log success
                publisher._logPublishRun(publishing_definition, sourceGr, 'update', 'success', httpStatus, page_id, page_url, version, '');
            } else {
                var updErrMsg = '';
                try {
                    var updErrObj = JSON.parse(responseBody);
                    updErrMsg = updErrObj.message || updErrObj.title || responseBody;
                } catch (e) {
                    updErrMsg = responseBody;
                }
                status = 'error';
                error_message = updErrMsg;
                page_id = existing_page_id;
                page_url = '';
                version = current_version;
                publisher._logPublishRun(publishing_definition, sourceGr, 'update', 'error', httpStatus, existing_page_id, '', current_version, updErrMsg, JSON.stringify({ pageId: existing_page_id, title: page_title }));
            }

        } else {
            status = 'error';
            error_message = 'Invalid operation: ' + operation + '. Expected create or update.';
            page_id = '';
            page_url = '';
            version = '';
        }

    } catch (e) {
        status = 'error';
        error_message = 'Exception during publish: ' + e.toString();
        page_id = '';
        page_url = '';
        version = '';
        gs.error('Publish Page to Confluence: ' + error_message);
    }
})();

